// Generated by Heron Brush for Cocos Creator 3.8. Re-exporting replaces this file; it
// is the same for every level, so export levels into one folder.
//
// Add HeronBrushLevel to a node and set `level` to the level file's path inside the
// resources bundle, without its extension (for example `levels/motion_lab`). On start
// it builds every entity under that node: the GLB models, colliders (a static mesh for
// world geometry, kinematic convex bodies for movers, triggers for trigger volumes),
// the editor's keyframe animation and trigger volumes, the editor's sky and sun, and
// water volumes: `water(point)` says which a point is in and how deep, each
// HeronWater's `velocity` swims, and with `view` set to the game's camera the camera
// sees the water's fog while it is under water.
//
// Cocos Creator's world is right-handed with Y up, in metres: the frame the level was
// written in, so nothing is converted.
import {
    _decorator, Component, Node, Prefab, JsonAsset, ImageAsset, Texture2D, TextureCube, instantiate, resources,
    Vec3, Quat, Color, MeshCollider, RigidBody, ERigidBodyType, utils, DirectionalLight, FogInfo, director, renderer, Camera,
    MeshRenderer, Material, gfx,
} from 'cc';

const { ccclass, property } = _decorator;

type Typed = { type: string; value: unknown };
export interface HeronEntity {
    name: string;
    classname: string;
    mesh?: string;
    targets?: string[];
    tags?: string[];
    transform: { translation: number[]; rotation_quaternion: number[]; scale: number[] };
    properties?: Record<string, Typed>;
    collision?: { kind: 'trimesh' | 'convex'; sensor?: boolean; triangles?: number[]; hulls?: number[][] };
}
interface Environment {
    faces: string[];
    to_sun: number[];
    sun_color: number[];
    sun_intensity: number;
    ambient_intensity: number;
    sky: number[];
    ground: number[];
    fog?: { color: number[]; density: number };
}
interface LevelFile { name: string; scale: number; entities: HeronEntity[]; environment?: Environment }

type Q = [number, number, number, number];
// The Hamilton product a*b: b's rotation, then a's.
const mul = (a: Q, b: Q): Q => [
    a[3] * b[0] + a[0] * b[3] + a[1] * b[2] - a[2] * b[1],
    a[3] * b[1] - a[0] * b[2] + a[1] * b[3] + a[2] * b[0],
    a[3] * b[2] + a[0] * b[1] - a[1] * b[0] + a[2] * b[3],
    a[3] * b[3] - a[0] * b[0] - a[1] * b[1] - a[2] * b[2]];
const axis = (x: number, y: number, z: number, angle: number): Q => { const s = Math.sin(angle / 2); return [x * s, y * s, z * s, Math.cos(angle / 2)]; };
const rotate = (q: Q, v: number[]): number[] => { const r = mul(mul(q, [v[0], v[1], v[2], 0]), [-q[0], -q[1], -q[2], q[3]]); return [r[0], r[1], r[2]]; };

interface Key { time: number; value: number; incoming: number; outgoing: number; interpolation: string }
interface Clip { name: string; mode: string; duration: number; channels: { keys: Key[] }[] }
const sample = (keys: Key[], time: number): number => {
    if (!keys.length) return 0;
    if (time <= keys[0].time) return keys[0].value;
    let i = 0;
    while (i + 1 < keys.length && keys[i + 1].time <= time) i++;
    const a = keys[i], b = keys[i + 1];
    if (!b || a.interpolation === 'hold') return a.value;
    const span = b.time - a.time, f = (time - a.time) / span, u = 1 - f;
    if (a.interpolation === 'bezier') return u * u * u * a.value + 3 * u * u * f * (a.value + a.outgoing * span / 3) +
        3 * u * f * f * (b.value - b.incoming * span / 3) + f * f * f * b.value;
    return a.value + (b.value - a.value) * f;
};

/** The editor's keyframe animation of one entity, as every Heron Brush runtime plays it. */
export class HeronAnimation {
    readonly data: { scale: number; pivot: number[]; selected: string; autoplay: boolean; clips: Clip[] };
    clip: Clip;
    time = 0;
    playing: boolean;
    posed: boolean;
    private position: number[];
    private rotation: Q;
    constructor(readonly node: Node, json: string) {
        this.data = JSON.parse(json);
        this.clip = this.data.clips.find(c => c.name === this.data.selected)!;
        this.playing = this.posed = this.data.autoplay;
        const p = node.position, r = node.rotation;
        this.position = [p.x, p.y, p.z];
        this.rotation = [r.x, r.y, r.z, r.w];
    }
    play(name?: string): boolean {
        const clip = this.data.clips.find(c => c.name === (name || this.data.selected));
        if (!clip) return false;
        this.clip = clip; this.time = 0; this.playing = this.posed = true; return true;
    }
    activate() {
        if (['open', 'close'].every(n => this.data.clips.some(c => c.name === n))) {
            const phase = Math.min(this.time / this.clip.duration, 1), reverse = this.playing && this.posed;
            this.play(this.clip.name === 'open' && this.posed ? 'close' : 'open');
            if (reverse) this.time = (1 - phase) * this.clip.duration;
        } else this.play(this.data.selected);
    }
    pause() { this.playing = false; }
    resume() { this.playing = this.posed = true; }
    stop() { this.playing = this.posed = false; this.time = 0; }
    update(dt: number) {
        const c = this.clip;
        if (this.playing) {
            this.time += dt;
            if (c.mode === 'once' && this.time >= c.duration) { this.time = c.duration; this.playing = false; }
            else if (c.mode !== 'once') this.time %= c.duration * (c.mode === 'pingpong' ? 2 : 1);
        }
        const r = this.rotation, p = this.position;
        if (!this.posed) { this.node.setPosition(p[0], p[1], p[2]); this.node.setRotation(r[0], r[1], r[2], r[3]); return; }
        let t = c.mode === 'once' ? Math.min(this.time, c.duration) : this.time % (c.duration * (c.mode === 'pingpong' ? 2 : 1));
        if (t > c.duration) t = 2 * c.duration - t;
        const v = c.channels.map(channel => sample(channel.keys, t)), rad = Math.PI / 180, s = this.data.scale, d = this.data.pivot;
        // Y, then X, then Z applied first: the YXZ order every Heron Brush runtime uses.
        const q = mul(mul(axis(0, 1, 0, v[5] * rad), axis(1, 0, 0, v[4] * rad)), axis(0, 0, 1, v[3] * rad));
        const pivot = [d[1] / s, d[2] / s, d[0] / s];
        const turned = rotate(q, [p[0] - pivot[0], p[1] - pivot[1], p[2] - pivot[2]]);
        this.node.setPosition(turned[0] + pivot[0] + v[1] / s, turned[1] + pivot[1] + v[2] / s, turned[2] + pivot[2] + v[0] / s);
        const out = mul(q, r);
        this.node.setRotation(out[0], out[1], out[2], out[3]);
    }
}

interface TriggerData { action?: string; clip?: string; once: boolean; wait: number; origin: number[]; volumes: number[][][]; targets?: string[] }
class HeronTrigger {
    inside = new Set<Node>();
    wait = 0;
    fired = false;
    pending = false;
    readonly data: TriggerData;
    constructor(readonly node: Node, json: string) { this.data = JSON.parse(json); }
    update(dt: number, activators: Node[], animations: Map<string, HeronAnimation>) {
        this.wait = Math.max(0, this.wait - dt);
        const d = this.data, inside = new Set<Node>(), back = new Vec3();
        for (const actor of activators) {
            if (!actor || !actor.isValid) continue;
            this.node.inverseTransformPoint(back, actor.worldPosition);
            const at = [back.x + d.origin[0], back.y + d.origin[1], back.z + d.origin[2]];
            if (d.volumes.some(planes => planes.length && planes.every(v => v[0] * at[0] + v[1] * at[1] + v[2] * at[2] <= v[3] + 1e-5))) inside.add(actor);
        }
        const entered = Array.from(inside).some(a => !this.inside.has(a));
        this.inside = inside;
        const requested = this.pending || entered; this.pending = false;
        if (!requested || this.wait > 0 || (d.once && this.fired)) return;
        this.wait = d.wait; this.fired = true;
        for (const name of d.targets || []) {
            const a = animations.get(name);
            if (!a) continue;
            switch (d.action) {
                case 'play': a.play(d.clip || a.data.selected); break;
                case 'open': case 'close': a.play(d.action); break;
                case 'pause': a.pause(); break;
                case 'resume': a.resume(); break;
                case 'stop': a.stop(); break;
                default: a.activate();
            }
        }
    }
}

interface WaterData {
    version: number; priority: number; volumes: { planes: { x: number; y: number; z: number; d: number }[]; surface: number }[];
    swim_speed: number; rise_speed: number; sink_speed: number; drag: number; color: number[]; opacity: number; fog_density: number;
}
/** One water volume: the entity's convex planes in its own frame, in metres. */
export class HeronWater {
    readonly data: WaterData;
    constructor(readonly node: Node, json: string) {
        this.data = JSON.parse(json);
        if (this.data.version !== 1) throw new Error(node.name + ': unsupported water payload');
    }
    /** How far below the surface `world` is, in metres, or -1 outside the water. */
    sample(world: Vec3): number {
        const p = new Vec3();
        this.node.inverseTransformPoint(p, world);
        let depth = -1;
        for (const v of this.data.volumes) {
            if (v.planes.length >= 4 && v.planes.every(q => q.x * p.x + q.y * p.y + q.z * p.z <= q.d + 1e-5))
                depth = Math.max(depth, (v.surface - p.y) * Math.abs(this.node.worldScale.y));
        }
        return depth;
    }
    /** Swimming: `walk` steers in the horizontal plane (capped at length 1), `rise`
     *  and `dive` move up and down, and with neither the body sinks slowly. The
     *  current velocity eases towards that at the volume's drag. */
    velocity(current: Vec3, walk: Vec3, rise: boolean, dive: boolean, dt: number, out = new Vec3()): Vec3 {
        const d = this.data, length = Math.hypot(walk.x, walk.y, walk.z), k = (length > 1 ? 1 / length : 1) * d.swim_speed;
        const wish = new Vec3(walk.x * k, (rise ? d.rise_speed : 0) - (dive ? d.rise_speed : 0) - (!rise && !dive ? d.sink_speed : 0), walk.z * k);
        return Vec3.lerp(out, current, wish, 1 - Math.exp(-d.drag * dt));
    }
}

const load = <T>(path: string, type: any): Promise<T> => new Promise((done, fail) =>
    resources.load(path, type, (error: Error | null, asset: T) => error ? fail(error) : done(asset)));

@ccclass('HeronBrushLevel')
export class HeronBrushLevel extends Component {
    @property({ tooltip: 'The level file inside the resources bundle, without its extension, e.g. levels/motion_lab' })
    level = '';
    @property({ tooltip: 'Add colliders from the level\'s collision' })
    physics = true;
    @property({ tooltip: 'Use the editor\'s sky, sun and fog for the scene' })
    environment = true;
    @property({ type: [Node], tooltip: 'Nodes that walk into trigger volumes, usually the player' })
    activators: Node[] = [];
    @property({ type: Node, tooltip: 'The game camera, which sees the water\'s fog while under water' })
    view: Node | null = null;

    /** Every entity's node by name, once loaded. */
    readonly entities = new Map<string, Node>();
    /** Every entity's record from the level file, typed properties included. */
    readonly records = new Map<string, HeronEntity>();
    readonly animations = new Map<string, HeronAnimation>();
    readonly waters: HeronWater[] = [];
    private triggers: HeronTrigger[] = [];
    /** Resolves when the level is built. */
    ready: Promise<void> | null = null;

    start() {
        if (this.level && !this.ready) this.ready = this.build(this.level);
    }

    /** Fires a trigger by name, as a button press does. */
    activate(name: string) {
        const t = this.triggers.find(t => t.node.name === name);
        if (t) t.pending = true;
    }

    async build(path: string): Promise<void> {
        const level = (await load<JsonAsset>(path, JsonAsset)).json as LevelFile;
        const folder = path.includes('/') ? path.slice(0, path.lastIndexOf('/') + 1) : '';
        // Every node exists before any is configured, so references resolve forwards.
        // They stay inactive until then: a collider reads its mesh when it first
        // becomes active, not when the mesh is set afterwards.
        for (const e of level.entities) {
            const node = new Node(e.name);
            node.active = false;
            const t = e.transform;
            node.setPosition(t.translation[0], t.translation[1], t.translation[2]);
            const [x, y, z, w] = t.rotation_quaternion;
            node.setRotation(x, y, z, w);
            node.setScale(t.scale[0], t.scale[1], t.scale[2]);
            node.setParent(this.node);
            this.entities.set(e.name, node);
            this.records.set(e.name, e);
        }
        const models: Promise<void>[] = [];
        for (const e of level.entities) {
            const node = this.entities.get(e.name)!;
            const water = e.properties?._heron_water?.value;
            if (e.mesh) models.push(this.attachModel(node, folder + e.mesh.replace(/\.glb$/, ''))
                .then(() => { if (typeof water === 'string') this.waterSurface(node, JSON.parse(water)); }));
            if (this.physics && e.collision) this.addCollider(node, e);
            const animation = e.properties?._heron_animation?.value;
            if (typeof animation === 'string') this.animations.set(e.name, new HeronAnimation(node, animation));
            const trigger = e.properties?._heron_trigger?.value;
            if (typeof trigger === 'string') this.triggers.push(new HeronTrigger(node, trigger));
            if (typeof water === 'string') this.waters.push(new HeronWater(node, water));
        }
        for (const node of this.entities.values()) node.active = true;
        if (this.environment && level.environment) models.push(this.applyEnvironment(folder, level.environment));
        await Promise.all(models);
    }

    private async attachModel(node: Node, path: string) {
        // A .glb imports as a glTF asset whose prefab is a sub-asset named after the file.
        const name = path.slice(path.lastIndexOf('/') + 1);
        let prefab: Prefab;
        try { prefab = await load<Prefab>(`${path}/${name}`, Prefab); }
        catch { prefab = await load<Prefab>(path, Prefab); }
        instantiate(prefab).setParent(node);
    }

    // Cocos imports a glTF material's colour but not its blending: the baseline water
    // surface is made here, see-through and seen from both sides, keeping its texture.
    private waterSurface(node: Node, data: WaterData & { surface_material: boolean }) {
        if (!data.surface_material) return;
        for (const renderer of node.getComponentsInChildren(MeshRenderer)) {
            const materials = renderer.sharedMaterials.map(old => {
                const texture = old ? old.getProperty('mainTexture') : null;
                const material = new Material();
                material.initialize({
                    effectName: 'builtin-standard', technique: 1, defines: { USE_ALBEDO_MAP: !!texture },
                    states: { rasterizerState: { cullMode: gfx.CullMode.NONE } },
                });
                const c = data.color;
                material.setProperty('mainColor', new Color(c[0] * 255, c[1] * 255, c[2] * 255, data.opacity * 255));
                material.setProperty('roughness', 0.14);
                material.setProperty('metallic', 0.05);
                if (texture) material.setProperty('mainTexture', texture);
                return material;
            });
            renderer.sharedMaterials = materials;
            renderer.shadowCastingMode = 0;
        }
    }

    private addCollider(node: Node, e: HeronEntity) {
        const c = e.collision!;
        // A convex collider reads only the points; the mesh still wants whole triangles.
        const mesh = (points: number[], triangles: boolean) => {
            const count = points.length / 3;
            // Array.from, not spread: Cocos compiles scripts to ES5, where spreading an
            // iterator gives an array holding the iterator.
            const indices: number[] = [];
            if (triangles) for (let i = 0; i < count; i++) indices.push(i);
            else for (let i = 1; i + 1 < count; i++) indices.push(0, i, i + 1);
            return utils.MeshUtils.createMesh({ positions: points, indices });
        };
        if (c.kind === 'convex' && !c.sensor) {
            const body = node.addComponent(RigidBody);
            body.type = ERigidBodyType.KINEMATIC;
            for (const hull of c.hulls || []) {
                const collider = node.addComponent(MeshCollider);
                collider.convex = true;
                collider.mesh = mesh(hull, false);
            }
            return;
        }
        const parts = c.triangles ? [c.triangles] : (c.hulls || []);
        for (const points of parts) {
            const collider = node.addComponent(MeshCollider);
            collider.convex = !c.triangles;
            collider.mesh = mesh(points, !!c.triangles);
            collider.isTrigger = !!c.sensor;
        }
    }

    private async applyEnvironment(folder: string, env: Environment) {
        const scene = director.getScene()!;
        const globals = scene.globals;
        const faces = await Promise.all(env.faces.map(face => load<ImageAsset>(folder + face, ImageAsset)));
        const cube = TextureCube.fromTexture2DArray(faces.map(image => { const t = new Texture2D(); t.image = image; return t; }));
        globals.skybox.enabled = true;
        globals.skybox.useIBL = true;
        globals.skybox.envmap = cube;
        const color = (c: number[]) => new Color(c[0] * 255, c[1] * 255, c[2] * 255, 255);
        globals.ambient.skyLightingColor = color(env.sky);
        globals.ambient.groundLightingColor = color(env.ground);
        // The scene's own directional light becomes the sun, or one is made.
        let sun = scene.getComponentInChildren(DirectionalLight);
        if (!sun) {
            const node = new Node('Heron sun');
            node.setParent(scene);
            sun = node.addComponent(DirectionalLight);
        }
        const to = new Vec3(env.to_sun[0], env.to_sun[1], env.to_sun[2]).normalize();
        // A light shines along its node's forward axis, -Z.
        const q = new Quat();
        Quat.rotationTo(q, new Vec3(0, 0, -1), new Vec3(-to.x, -to.y, -to.z));
        sun.node.setWorldRotation(q);
        sun.color = color(env.sun_color);
        sun.illuminanceLDR = env.sun_intensity / Math.PI;
        sun.shadowEnabled = true;
        globals.shadows.enabled = true;
        globals.shadows.type = renderer.scene.ShadowType.ShadowMap;
        if (env.fog) {
            globals.fog.enabled = true;
            globals.fog.type = FogInfo.FogType.EXP;
            globals.fog.fogColor = color(env.fog.color);
            globals.fog.fogDensity = env.fog.density;
        }
    }

    /** The volume `world` is in and how deep; where volumes overlap the higher
     *  priority wins, then the deeper. */
    water(world: Vec3): { water: HeronWater; depth: number } | null {
        let best: { water: HeronWater; depth: number } | null = null;
        for (const water of this.waters) {
            if (!water.node.activeInHierarchy) continue;
            const depth = water.sample(world);
            if (depth < 0) continue;
            if (!best || water.data.priority > best.water.data.priority || (water.data.priority === best.water.data.priority && depth > best.depth))
                best = { water, depth };
        }
        return best;
    }

    private saved: { fog: boolean; type: number; color: Color; density: number; flags: number; clear: Color } | null = null;
    private underwater() {
        const camera = this.view?.getComponent(Camera);
        const found = camera ? this.water(camera.node.worldPosition) : null;
        const globals = director.getScene()?.globals;
        if (!globals || !camera) return;
        if (found) {
            const fog = globals.fog;
            if (!this.saved) this.saved = { fog: fog.enabled, type: fog.type, color: fog.fogColor.clone(), density: fog.fogDensity, flags: camera.clearFlags, clear: camera.clearColor.clone() };
            const c = found.water.data.color, color = new Color(c[0] * 255, c[1] * 255, c[2] * 255, 255);
            fog.enabled = true;
            fog.type = FogInfo.FogType.EXP;
            fog.fogColor = color;
            fog.fogDensity = found.water.data.fog_density;
            // Fog does not reach the sky, which would show through clear water.
            camera.clearFlags = Camera.ClearFlag.SOLID_COLOR;
            camera.clearColor = color;
        } else if (this.saved) {
            const fog = globals.fog, s = this.saved;
            fog.enabled = s.fog; fog.type = s.type; fog.fogColor = s.color; fog.fogDensity = s.density;
            camera.clearFlags = s.flags; camera.clearColor = s.clear;
            this.saved = null;
        }
    }

    update(dt: number) {
        for (const t of this.triggers) t.update(dt, this.activators, this.animations);
        for (const a of this.animations.values()) a.update(dt);
        if (this.waters.length) this.underwater();
    }
}
